### Wall bar (content type navigation links)

The wall bar icons are created in `createWalls()` at `D:\code\tutors\node_modules\@tutors\tutors-model-lib\src\utils\course-utils.ts` (lines 102-113):

```ts
export function createWalls(course: Course) {
  course.walls = [];
  course.wallMap = new Map<string, Lo[]>();
  ["talk", "tutorial", "note", "lab", "podcast", "web", "archive", "github"].forEach((type) =>
    addWall(course, type as LoType)
  );
  course.wallBar = { show: true, bar: [] };
  course.walls?.forEach((wall) => {
    course.wallBar.bar.push(createWallLink(wall[0].type, course));
  });
}
```

Each wall link routes to `/wall/${type}/${course.courseId}`. The wall icons appear in the `SecondaryNavigator` as an `<IconBar nav={currentCourse?.value?.wallBar} />`.

